export function savedShopButton(s,id,{esc}){
 const saved=(s.savedShops||[]).includes(id);return `<button class="button secondary" data-action="toggle-saved-shop" data-id="${esc(id)}" aria-pressed="${saved}">${saved?'Saved shop ✓ · remove':'Save this shop'}</button>`;
}
export function pendingCollection(s,st,{E,esc}){
 const ids=new Set(E.mallOf(s).sections.flatMap(d=>d.stores)),floor=E.storeFloor(E.mallOf(s),st.id),alternatives=E.STORES.filter(v=>ids.has(v.id)&&v.count).sort((a,b)=>(E.storeFloor(E.mallOf(s),a.id)!==floor)-(E.storeFloor(E.mallOf(s),b.id)!==floor)||a.name.localeCompare(b.name)).slice(0,4);
 return `<div class="modal-body catalog-pending collection-guide"><span class="eyebrow">EXPLORE & PLAN</span><h3>This collection is still being researched.</h3><p>You can explore the shop, speak with its associate and save the location. Purchases, fitting and demos become available when verified merchandise is added.</p>${E.isPlanningStore(st)?`<section class="planning-invitation"><h3>Make your next stop a good one.</h3><p>Use this original planning lounge to compare verified finds at their actual shops, set a game budget and save a three-item shortlist.</p><button class="button orange" data-action="shop-plan-open" data-id="${esc(st.id)}">Build a shopping shortlist</button><button class="button secondary" data-action="plan-notebook">My saved shortlists</button></section>`:''}<div class="collection-guide-actions">${savedShopButton(s,st.id,{esc})}<button class="button secondary" data-action="collection-associate" data-id="${esc(st.id)}">Meet the associate</button><button class="button orange" data-action="shop-stocked">Find stocked shops</button></div><h3>Verified collections at this center</h3><div class="collection-alternatives">${alternatives.map(v=>`<button class="button secondary" data-action="visit" data-id="${esc(v.id)}"><strong>${esc(v.name)}</strong><small>${v.count} real products · ${esc(E.planFor(s).levels[E.storeFloor(E.mallOf(s),v.id)])}</small></button>`).join('')}</div><p class="hint">Saving a shop keeps a waypoint in this mode’s Shops → Saved list. It spends no money and does not reserve stock.</p><div class="service-links">${st.source?`<a href="${esc(st.source)}" target="_blank" rel="noopener noreferrer">Official location reference ↗</a>`:''}<button class="button secondary" data-action="leave-shop">Exit shop → Mall</button></div></div>`;
}
